describe('Async Image Upload with Progress Percentage', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should display progress percentage during async image upload', () => {
    // Setup: intercept the upload API endpoint
    cy.intercept('POST', '/api/upload', (req) => {
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: {
            success: true,
            fileUrl: '/uploads/test-image.jpg',
            progress: 100
          }
        });
      });
    }).as('uploadImage');

    // Get the file input and select a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-image.jpg', {
      force: true
    });

    // Click the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Verify upload button is disabled and progress indicator appears
    cy.get('[data-testid="upload-button"]').should('be.disabled');
    cy.get('[data-testid="progress-container"]').should('be.visible');

    // Verify progress percentage is displayed
    cy.get('[data-testid="progress-percentage"]').should('contain', '0%');

    // Wait for the upload API call to complete
    cy.wait('@uploadImage');

    // Verify progress reaches 100%
    cy.get('[data-testid="progress-percentage"]').should('contain', '100%');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Upload successful');

    // Verify file URL is displayed
    cy.get('[data-testid="file-url"]').should('contain', '/uploads/test-image.jpg');

    // Verify upload button is re-enabled
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');
  });

  it('should handle upload failure and display error message', () => {
    // Setup: intercept the upload API endpoint to simulate failure
    cy.intercept('POST', '/api/upload', {
      statusCode: 500,
      body: {
        success: false,
        error: 'Server error during upload'
      }
    }).as('uploadImageFailure');

    // Select a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-image.jpg', {
      force: true
    });

    // Click the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Verify progress indicator appears
    cy.get('[data-testid="progress-container"]').should('be.visible');

    // Wait for the failed upload API call
    cy.wait('@uploadImageFailure');

    // Verify progress percentage is displayed (even on failure)
    cy.get('[data-testid="progress-percentage"]').should('contain', '100%');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Upload failed');

    // Verify success message is NOT displayed
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify upload button is re-enabled
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Verify error icon is visible
    cy.get('[data-testid="error-icon"]').should('be.visible');
  });
});
